// generated by scripts/build_frontend.py from the design page; do not edit
/* ---------- data from the API: company, buyer_org, tender, participation and contract totals ---------- */
const API = (window.API_BASE || '').replace(/\/$/, ''), NAME = 'Tenderbook';
let COMPANY = null, PART = [], T = {}, A = {}, C = {}, CT = {}, BY_TENDER = {}, INDIA = [], LIMITED = false, RIVALS = {};
const LOADED = new Set();
const END = new Date();
const NO_AUTH = { organisation: 'Unknown authority', ministry: '', department: '', office: '', state: null };
async function getJSON(path) {
  const r = await fetch(API + path, { headers: { Accept: 'application/json' } });
  if (!r.ok) throw new Error(r.status === 429 ? 'Too many requests. Wait a minute and try again.'
    : r.status === 404 ? 'This company was not found.' : 'The server could not answer (' + r.status + '). Try again in a moment.');
  return r.json();
}
async function loadCompany(id) {
  const d = await getJSON('/api/company?id=' + encodeURIComponent(id));
  COMPANY = d.company; PART = d.part; LIMITED = d.limited; RIVALS = d.rivals;
  T = Object.fromEntries(d.tenders.map(t => [t.tender_id, t]));
  A = Object.fromEntries(d.authorities.map(a => [a.buyer_org_id, a]));
  C = Object.fromEntries([COMPANY, ...d.companies].map(c => [c.company_id, c]));
  CT = Object.fromEntries(d.contracts.map(c => [c.tender_id + ':' + c.company_id, c.total]));
  BY_TENDER = {};
  for (const p of PART) if (T[p.tender_id]) (BY_TENDER[p.tender_id] ||= []).push(p);
}
async function loadRival(id) {
  if (LOADED.has(id)) return;
  const d = await getJSON('/api/rival?id=' + COMPANY.company_id + '&rival=' + id);
  for (const p of d.part) if (T[p.tender_id]) { PART.push(p); (BY_TENDER[p.tender_id] ||= []).push(p); }
  LOADED.add(id);
}

/* ---------- views over the data (what company_history, company_summary, company_org and company_competitor hold) ---------- */
const state = { section: 'overview', period: 'all', org: { filter: 'awarded', metric: 'amount', state: null }, bids: { q: '', f: 'all', page: 0 },
  auth: { q: '' }, comp: { q: '', sort: 'met', id: null } };
const PERIODS = [['12m', '12 months', 365], ['24m', '24 months', 730], ['all', 'All time', 99999]];
function inPeriod(t) { const days = PERIODS.find(p => p[0] === state.period)[2]; return (END - new Date(t.bid_end_at)) / 864e5 <= days; }
function bidRows() {
  return PART.filter(p => p.company_id === COMPANY.company_id && T[p.tender_id] && inPeriod(T[p.tender_id]))
    .map(p => { const t = T[p.tender_id], a = A[t.buyer_org_id] || NO_AUTH; return { ...p, ...t, ...{ organisation: a.organisation, ministry: a.ministry, department: a.department, office: /^\*+$/.test(a.office || '') ? '' : a.office, state: t.state || a.state }, contract_total: CT[p.tender_id + ':' + p.company_id] ?? null }; })
    .sort((a, b) => b.bid_end_at.localeCompare(a.bid_end_at));
}
const won = h => h.outcome === 1;
const value = h => h.contract_total ?? h.offered_price ?? 0;
function summary(H) {
  const q = H.filter(h => h.tech_status === 1), w = H.filter(won), decided = H.filter(h => h.outcome !== 0);
  const dates = H.map(h => h.bid_end_at).sort();
  return { bids: H.length, qualified: q.length, won: w.length, value: w.reduce((s, h) => s + value(h), 0),
    rate: decided.length ? w.length / decided.length : null, rate_q: q.length ? w.length / q.length : null,
    buyers: new Set(H.map(h => h.buyer_org_id)).size, states: new Set(H.map(h => h.state).filter(Boolean)).size,
    by_contract: w.filter(h => h.outcome_source === 1).length, pending: H.filter(h => h.outcome === 0).length,
    rejected: H.filter(h => h.tech_status === 2).length, first: dates[0], last: dates[dates.length - 1] };
}
function months(H, split) {
  const out = {}, end = new Date(END);
  const span = state.period === '12m' ? 12 : state.period === '24m' ? 24 : 30;
  for (let i = span - 1; i >= 0; i--) { const d = new Date(end.getFullYear(), end.getMonth() - i, 1); out[d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')] = split(null); }
  for (const h of H) { const k = h.bid_end_at.slice(0, 7); if (out[k]) split(out[k], h); }
  return Object.entries(out);
}
function rivals(H) {
  return (RIVALS[state.period] || []).map(r => ({ ...r, c: C[r.id] })).filter(r => r.c);
}

/* ---------- formatting ---------- */
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = n => n == null ? '—' : Number(n).toLocaleString('en-IN');
const pct = (r, d = 1) => r == null ? '—' : (r * 100).toFixed(d) + '%';
function inr(v) {
  if (v == null) return '—'; v = Number(v);
  if (v >= 1e7) return '₹' + (v / 1e7).toLocaleString('en-IN', { maximumFractionDigits: v >= 1e9 ? 0 : 2 }) + ' Cr';
  if (v >= 1e5) return '₹' + (v / 1e5).toFixed(1) + ' L';
  return '₹' + Math.round(v).toLocaleString('en-IN');
}
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
