  const counts = { bids: s.bids, authorities: s.buyers, competitors: rv.length };
  const items = SECTIONS.map(([k, l]) => `<button class="sideitem${state.section === k ? ' on' : ''}" data-go="${k}">${icon(k)}<span>${l}</span>${counts[k] != null ? `<span class="ct">${num(counts[k])}</span>` : ''}</button>`).join('');
