  document.getElementById('crumbs').innerHTML = `<a class="crumblink" href="./">Companies</a><span class="sepc">/</span><span class="trunc">${esc(short(COMPANY.display_name))}</span><span class="sepc">/</span><span>${SECTIONS.find(x => x[0] === state.section)[1]}</span>`;
  document.getElementById('period').innerHTML = PERIODS.map(([k, l]) => `<button class="${state.period === k ? 'on' : ''}" data-period="${k}">${l}</button>`).join('');
