/* ---------- organisations panel with India map ---------- */
const OFILTERS = [['awarded', 'Awarded', won], ['participated', 'Participated', () => true], ['lost', 'Lost', h => h.outcome === 2 && h.tech_status !== 2],
  ['rejected', 'Tech rejected', h => h.tech_status === 2], ['pending', 'Pending', h => h.outcome === 0]];
const PALETTE = ['var(--c1)', 'var(--c2)', 'var(--c3)', 'var(--c4)', 'var(--c5)'];
function orgData(H) {
  const o = state.org, f = OFILTERS.find(x => x[0] === o.filter)[2];
  const metric = o.filter === 'rejected' ? 'count' : o.metric;
  const amt = h => o.filter === 'awarded' ? value(h) : (h.offered_price || 0);
  const rows = H.filter(f), orgs = {}, states = {};
  for (const h of rows) {
    const v = metric === 'amount' ? amt(h) : 1;
    const g = (orgs[h.organisation] ||= { name: h.organisation, ministry: h.ministry, states: new Set(), v: 0, n: 0 }); g.v += v; g.n++; if (h.state) g.states.add(h.state);
    if (h.state) { const s = (states[h.state] ||= { name: h.state, v: 0, n: 0, orgs: new Set() }); s.v += v; s.n++; s.orgs.add(h.organisation); }
  }
  const total = Object.values(states).reduce((t, s) => t + s.v, 0);
  return { metric, total, orgs: Object.values(orgs), states: Object.values(states).sort((a, b) => b.v - a.v), allOrgs: new Set(H.map(h => h.organisation)).size, allStates: new Set(H.map(h => h.state).filter(Boolean)).size };
}
const fmtV = (v, metric) => metric === 'amount' ? inr(v) : num(v) + (v === 1 ? ' bid' : ' bids');
function orgPanel(H, i, full) {
  const o = state.org, d = orgData(H);
  let orgs = d.orgs.filter(g => !o.state || g.states.has(o.state)).sort((a, b) => b.v - a.v);
  if (o.state) {   // within one state, count only that state's share of each organisation
    const f = OFILTERS.find(x => x[0] === o.filter)[2];
    orgs = orgs.map(g => { const r = H.filter(h => f(h) && h.organisation === g.name && h.state === o.state); return { ...g, v: r.reduce((t, h) => t + (d.metric === 'amount' ? (o.filter === 'awarded' ? value(h) : h.offered_price || 0) : 1), 0) }; }).sort((a, b) => b.v - a.v);
  }
  const otot = orgs.reduce((t, g) => t + g.v, 0) || 1, top = orgs.slice(0, full ? 12 : 5), rest = orgs.slice(top.length);
  const restV = rest.reduce((t, g) => t + g.v, 0), maxO = Math.max(1e-9, ...top.map(g => g.v), restV);
  const orgRows = top.map((g, j) => `<div class="orow"><span class="od" style="--c:${PALETTE[j] || 'var(--c6)'}"></span><span style="min-width:0"><span class="on" style="display:block">${esc(g.name)}</span><span class="os">${esc(g.ministry)}</span></span>
      <span class="ov">${fmtV(g.v, d.metric)}<span class="op">${pct(g.v / otot)}</span></span>${bar(g.v / maxO, PALETTE[j] || 'var(--c6)')}</div>`).join('')
    + (rest.length ? `<div class="orow"><span class="od" style="--c:var(--c6)"></span><span class="on" style="color:var(--muted)">+ ${rest.length} others</span><span class="ov">${fmtV(restV, d.metric)}<span class="op">${pct(restV / otot)}</span></span>${bar(restV / maxO, 'var(--c6)')}</div>` : '');
  const maxS = Math.max(1e-9, ...d.states.map(s => s.v));
  const stateRows = d.states.map(s => `<button class="srow${o.state === s.name ? ' sel' : ''}" data-state="${esc(s.name)}"><span class="sn">${esc(s.name)}</span><span class="sv">${fmtV(s.v, d.metric)}</span>
      ${bar(s.v / maxS, 'var(--accent)')}<span class="sp">${pct(s.v / (d.total || 1))}</span></button>`).join('');
  const seg = OFILTERS.map(([k, l]) => `<button class="${o.filter === k ? 'on' : ''}" data-ofilter="${k}">${l}</button>`).join('');
  const metric = `<button class="${d.metric === 'amount' ? 'on' : ''}" data-metric="amount" ${o.filter === 'rejected' ? 'disabled title="Rejected bids have no price"' : ''}>Amount</button><button class="${d.metric === 'count' ? 'on' : ''}" data-metric="count">Count</button>`;
  const empty = `<div class="empty"><strong>No ${OFILTERS.find(x => x[0] === o.filter)[1].toLowerCase()} bids</strong><span>Try another result or a longer period.</span></div>`;
  return `<section class="card orgpanel rise" style="--i:${i}">
    <div class="orghead"><div class="t"><h2>Authorities</h2><span class="sub mono muted small">${num(d.allOrgs)} authorities · ${num(d.allStates)} states</span></div>
      <div class="row gap8 wrapf"><div class="seg" role="group" aria-label="Result">${seg}</div><div class="seg acc" role="group" aria-label="Measure">${metric}</div></div></div>
    <div class="orgbody">
      <section><div class="phead"><h3>Top authorities${o.state ? ' in ' + esc(o.state) : ''}</h3>${o.state ? `<button class="link" data-state="${esc(o.state)}">Clear state</button>` : full ? '' : `<button class="link" data-go="authorities">View all ${num(d.allOrgs)} ${icon('arrow', 14)}</button>`}</div>${orgs.length ? orgRows : empty}</section>
      <section><div class="phead"><h3>Operating states</h3><span class="sub">${num(d.states.length)} states · click to filter</span></div>
        ${d.states.length ? `<div class="maparea"><div class="mapbox" id="mapbox"><div class="maplg"><div class="grad"></div><div class="row" style="justify-content:space-between;gap:10px"><span>${fmtV(Math.min(...d.states.map(s => s.v)), d.metric)}</span><span>${fmtV(maxS, d.metric)}</span></div></div>${mapSvg(d)}</div>
        <div class="statelist">${stateRows}</div></div>` : empty}</section>
    </div></section>`;
}
function mapSvg(d) {
  const by = Object.fromEntries(d.states.map(s => [s.name, s])), max = Math.max(1e-9, ...d.states.map(s => s.v));
  const paths = INDIA.map(p => {
    const s = by[p.name], f = s ? .12 + .88 * Math.sqrt(s.v / max) : 0;
    const fill = s ? `color-mix(in srgb,var(--accent) ${(f * 100).toFixed(0)}%,var(--map-land))` : 'var(--map-land)';
    const cls = state.org.state ? (state.org.state === p.name ? 'sel' : 'dim') : '';
    return `<path d="${p.d}" data-name="${esc(p.name)}" class="${cls}" style="fill:${fill}"/>`;
  }).join('');
  return `<svg viewBox="0 0 612 696" role="img" aria-label="Map of India shaded by ${d.metric}">${paths}</svg>`;
}
function wireMap(H) {
  const box = document.getElementById('mapbox');
  if (!box) return;
  const d = orgData(H), by = Object.fromEntries(d.states.map(s => [s.name, s]));
  let tip = null;
  box.addEventListener('mousemove', e => {
    const p = e.target.closest('path');
    if (!p) { tip && tip.remove(); tip = null; return; }
    const s = by[p.dataset.name];
    if (!tip) { tip = document.createElement('div'); tip.className = 'maptip'; box.appendChild(tip); }
    tip.innerHTML = `<b>${esc(p.dataset.name)}</b>` + (s ? `<div class="r"><span>${d.metric === 'amount' ? 'Amount' : 'Bids'}</span><span>${fmtV(s.v, d.metric)}</span></div>
      <div class="r"><span>Share</span><span>${pct(s.v / (d.total || 1))}</span></div><div class="r"><span>Authorities</span><span>${s.orgs.size}</span></div>` : `<div class="r"><span>No bids here</span><span></span></div>`);
    const r = box.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
    tip.style.left = Math.min(x + 14, r.width - 175) + 'px'; tip.style.top = Math.max(6, y - 70) + 'px';
  });
  box.addEventListener('mouseleave', () => { tip && tip.remove(); tip = null; });
}

/* ---------- bids ---------- */
const BFILTERS = [['all', 'All', () => true], ['won', 'Won', won], ['lost', 'Lost', h => h.outcome === 2 && h.tech_status !== 2], ['pending', 'Pending', h => h.outcome === 0], ['rejected', 'Rejected', h => h.tech_status === 2]];
function result(h) {
  if (h.tech_status === 2) return `<span class="badge badge-crit">Rejected</span>`;
  if (h.outcome === 1) return `<span class="row gap6 wrapf"><span class="badge badge-good">Won</span><span class="evi${h.outcome_source === 1 ? ' ver' : ''}">${h.outcome_source === 1 ? 'Contract' : 'Sole L1'}</span></span>`;
  if (h.outcome === 2) return `<span class="badge">Lost</span>`;
  return `<span class="badge badge-warn">Pending</span>`;
}
function bidsView(H) {
  const b = state.bids, q = b.q.trim().toLowerCase();
  const rows = H.filter(BFILTERS.find(x => x[0] === b.f)[2]).filter(h => !q || [h.bid_number, h.ra_number, h.category, h.organisation, h.state].some(x => (x || '').toLowerCase().includes(q)));
  const per = 25, pages = Math.max(1, Math.ceil(rows.length / per)); b.page = Math.min(b.page, pages - 1);
  const chips = BFILTERS.map(([k, l, f]) => `<button class="chip${b.f === k ? ' on' : ''}" data-bf="${k}">${l}<span class="n">${num(H.filter(f).length)}</span></button>`).join('');
  const body = rows.slice(b.page * per, b.page * per + per).map(h => `<tr>
      <td class="num" style="white-space:nowrap">${day(h.bid_end_at)}</td>
      <td><span class="mono small">${esc(h.bid_number)}</span>${h.ra_number ? `<span class="sub mono">RA ${esc(h.ra_number)}</span>` : ''}</td>
      <td style="max-width:300px"><span class="trunc" style="display:block" title="${esc(h.category)}">${esc(h.category)}</span><span class="sub">${esc(h.offered_make)} · ${esc(h.offered_model)} · qty ${num(h.quantity)}</span></td>
      <td class="hide-sm" style="max-width:260px"><span class="trunc" style="display:block">${esc(h.organisation)}</span><span class="sub trunc">${esc([h.office, h.state].filter(Boolean).join(', ') || '—')}</span></td>
      <td>${h.price_rank ? `<span class="rank${h.price_rank === 1 ? ' l1' : ''}">L${h.price_rank}</span>` : '<span class="faint">—</span>'}</td>
      <td class="r">${inr(h.offered_price)}${h.contract_total ? `<span class="sub">contract ${inr(h.contract_total)}</span>` : ''}</td>
      <td>${result(h)}</td></tr>`).join('');
  return `<div class="pagehead rise" style="--i:0"><div class="eyebrow">Bids</div><h1 style="margin-top:4px">Every bid on an awarded tender</h1></div>
    <section class="card rise" style="--i:1">
      <div class="toolbar"><div class="row gap6 wrapf">${chips}</div>
        <div class="search" style="margin-left:auto;width:min(320px,100%)">${icon('search', 15)}<input class="input" id="bq" type="search" placeholder="Bid number, category, authority or state" value="${esc(b.q)}" aria-label="Search bids"></div></div>
      ${rows.length ? `<div class="scroll-x"><table class="tbl"><thead><tr><th>Bid end</th><th>Bid</th><th>Category</th><th class="hide-sm">Authority</th><th>Rank</th><th class="r">Offered</th><th>Result</th></tr></thead><tbody>${body}</tbody></table></div>`
        : `<div class="empty"><strong>No bids match</strong><span>Clear the search or pick another result.</span></div>`}
      <div class="pager"><span>${num(rows.length)} bids · page ${b.page + 1} of ${pages}</span><span class="row gap6"><button class="btn" data-page="-1" ${b.page ? '' : 'disabled'}>Previous</button><button class="btn" data-page="1" ${b.page < pages - 1 ? '' : 'disabled'}>Next</button></span></div>
    </section>`;
}

/* ---------- authorities ---------- */
function authView(H) {
  const q = state.auth.q.trim().toLowerCase(), m = {};
  for (const h of H) {
    const a = (m[h.buyer_org_id] ||= { ...(A[h.buyer_org_id] || NO_AUTH), bids: 0, won: 0, value: 0, last: '' });
    a.bids++; if (won(h)) { a.won++; a.value += value(h); } if (h.bid_end_at > a.last) a.last = h.bid_end_at;
  }
  const rows = Object.values(m).filter(a => !q || [a.organisation, a.office, a.ministry, a.state].some(x => (x || '').toLowerCase().includes(q))).sort((a, b) => b.value - a.value || b.bids - a.bids);
  const body = rows.map(a => `<tr><td style="max-width:380px"><span class="name trunc" style="display:block">${esc(a.organisation)}</span><span class="sub trunc">${esc([/^\*+$/.test(a.office || '') ? '' : a.office, a.ministry].filter(Boolean).join(' · '))}</span></td>
      <td class="hide-sm">${esc(a.state || '—')}</td><td class="r">${num(a.bids)}</td><td class="r">${num(a.won)}</td><td class="r">${pct(a.won / a.bids, 0)}</td><td class="r"><b>${inr(a.value)}</b></td><td class="hide-sm" style="white-space:nowrap">${day(a.last)}</td></tr>`).join('');
  return `<div class="pagehead rise" style="--i:0"><div class="eyebrow">Authorities</div><h1 style="margin-top:4px">Who this company sells to</h1></div>
    ${orgPanel(H, 1, true)}
    <section class="card rise" style="--i:2"><div class="toolbar"><h3>Every buying office</h3>
      <div class="search" style="margin-left:auto;width:min(320px,100%)">${icon('search', 15)}<input class="input" id="aq" type="search" placeholder="Authority, office, ministry or state" value="${esc(state.auth.q)}" aria-label="Search authorities"></div></div>
      ${rows.length ? `<div class="scroll-x"><table class="tbl"><thead><tr><th>Authority</th><th class="hide-sm">State</th><th class="r">Bids</th><th class="r">Won</th><th class="r">Win rate</th><th class="r">Awarded value</th><th class="hide-sm">Last bid</th></tr></thead><tbody>${body}</tbody></table></div>`
        : `<div class="empty"><strong>No authority matches</strong><span>Clear the search to see all of them.</span></div>`}</section>`;
}

/* ---------- competitors: list + head to head ---------- */
function compView(H) {
  const all = rivals(H), sel = all.find(r => r.id === state.comp.id);
  if (state.comp.id != null && sel) return `<div class="backrow rise" style="--i:0"><button class="btn" data-back="1">${icon('back', 15)}All competitors</button>
      <span class="small muted">${esc(title(sel.c.display_name))}</span></div>${h2h(H, sel)}`;
  const q = state.comp.q.trim().toLowerCase();
  const list = all.filter(r => !q || r.c.display_name.toLowerCase().includes(q))
    .sort(state.comp.sort === 'won' ? (a, b) => b.their_wins - a.their_wins || b.shared - a.shared : state.comp.sort === 'beat' ? (a, b) => (b.lost_to - b.beat) - (a.lost_to - a.beat) : (a, b) => b.shared - a.shared);
  const sorts = [['met', 'Met most'], ['won', 'They won most'], ['beat', 'Undercut you']].map(([k, l]) => `<button class="${state.comp.sort === k ? 'on' : ''}" data-csort="${k}">${l}</button>`).join('');
  const rows = list.map(r => {
    const rest = Math.max(0, r.shared - r.our_wins - r.their_wins);
    return `<tr class="clickable" data-vs="${r.id}" tabindex="0">
      <td><span class="row gap10"><span class="av sm them">${initials(r.c.display_name)}</span><span class="name">${esc(title(r.c.display_name))}</span></span></td>
      <td class="r">${num(r.shared)}</td><td class="r"><span class="us-n">${num(r.our_wins)}</span></td><td class="r"><span class="th-n">${num(r.their_wins)}</span></td>
      <td class="hide-sm"><span class="mtug" title="You ${r.our_wins}, them ${r.their_wins}, others ${rest}">${r.our_wins ? `<i style="flex:${r.our_wins};background:var(--accent)"></i>` : ''}${rest ? `<i style="flex:${rest};background:var(--surface-3)"></i>` : ''}${r.their_wins ? `<i style="flex:${r.their_wins};background:var(--warn)"></i>` : ''}</span></td>
      <td class="r hide-sm">${num(r.beat)} / ${num(r.lost_to)}</td>
      <td class="hide-sm" style="white-space:nowrap">${day(r.last)}</td><td class="go">${icon('arrow', 15)}</td></tr>`;
  }).join('');
  return `<div class="pagehead rise" style="--i:0"><div class="eyebrow">Competitors</div><h1 style="margin-top:4px">Who this company bids against</h1></div>
    <section class="card rise" style="--i:1">
      <div class="toolbar"><div class="search" style="width:min(340px,100%)">${icon('search', 15)}<input class="input" id="cq" type="search" placeholder="Search competitors" value="${esc(state.comp.q)}" aria-label="Search competitors"></div>
        <div class="seg" role="group" aria-label="Sort competitors">${sorts}</div><span class="sub small muted" style="margin-left:auto">${num(list.length)} of ${num(all.length)}</span></div>
      ${list.length ? `<div class="scroll-x"><table class="tbl"><thead><tr><th>Competitor</th><th class="r">Met on</th><th class="r">You won</th><th class="r">They won</th><th class="hide-sm">Shared bids</th><th class="r hide-sm">Cheaper / dearer</th><th class="hide-sm">Last met</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`
        : `<div class="empty"><strong>No competitor matches “${esc(state.comp.q)}”</strong><span>Try part of the name.</span></div>`}
      <p class="tiny muted" style="padding:4px 20px 18px">Open a competitor to see the head to head. Cheaper / dearer counts the shared bids where your price ranked above or below theirs.</p>
    </section>`;
}
function h2h(H, r) {
  const shared = H.filter(h => BY_TENDER[h.tender_id].some(p => p.company_id === r.id))
    .map(h => ({ us: h, them: BY_TENDER[h.tender_id].find(p => p.company_id === r.id), t: h })).sort((a, b) => b.t.bid_end_at.localeCompare(a.t.bid_end_at));
  const other = shared.filter(x => x.us.outcome !== 1 && x.them.outcome !== 1 && x.us.outcome !== 0).length;
  const n = shared.length, ourW = r.our_wins, theirW = r.their_wins, pend = n - ourW - theirW - other;
  const both = shared.filter(x => x.us.offered_price && x.them.offered_price);
  const gap = both.length ? both.reduce((t, x) => t + (x.us.offered_price - x.them.offered_price) / x.them.offered_price, 0) / both.length : null;
  const avgRank = side => { const v = shared.map(x => x[side].price_rank).filter(Boolean); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
  const metrics = [
    ['Wins when both bid', ourW, theirW, true],
    ['Finished L1', shared.filter(x => x.us.price_rank === 1).length, shared.filter(x => x.them.price_rank === 1).length, true],
    ['Lower price of the two', r.beat, r.lost_to, true],
    ['Average price rank', avgRank('us'), avgRank('them'), false, v => v == null ? '—' : v.toFixed(2)],
    ['Rejected in technical', shared.filter(x => x.us.tech_status === 2).length, shared.filter(x => x.them.tech_status === 2).length, false],
    ['Won by contract', shared.filter(x => x.us.outcome === 1 && x.us.outcome_source === 1).length, shared.filter(x => x.them.outcome === 1 && x.them.outcome_source === 1).length, true],
  ];
  const cmpRows = metrics.map(([l, a, b, hi, f]) => {
    const fm = f || num, mx = Math.max(1e-9, a || 0, b || 0);
    const aBetter = a != null && b != null && (hi ? a > b : a < b), bBetter = a != null && b != null && (hi ? b > a : b < a);
    return `<div class="cmp"><span class="cv l ${aBetter ? 'better' : bBetter ? 'worse' : ''}">${fm(a)}${bar((a || 0) / mx, 'var(--accent)')}</span><span class="ml">${l}</span><span class="cv ${bBetter ? 'better' : aBetter ? 'worse' : ''}">${bar((b || 0) / mx, 'var(--warn)')}${fm(b)}</span></div>`;
  }).join('');
  const m = months(shared.map(x => x.us), (o, h) => { if (!o) return { us: 0, them: 0, oth: 0 }; const th = BY_TENDER[h.tender_id].find(p => p.company_id === r.id); if (h.outcome === 1) o.us++; else if (th.outcome === 1) o.them++; else o.oth++; });
  const cats = {}; for (const x of shared) cats[x.t.category] = (cats[x.t.category] || 0) + 1;
  const catChips = Object.entries(cats).filter(([k]) => k && k !== 'null').sort((a, b) => b[1] - a[1]).map(([k, v]) => `<span class="badge" title="${esc(k)}">${esc(k.length > 46 ? k.slice(0, 44) + '…' : k)} <span class="mono">${v}</span></span>`).join('');
  const table = shared.slice(0, 40).map(x => `<tr><td style="white-space:nowrap">${day(x.t.bid_end_at)}</td>
      <td><span class="mono small">${esc(x.t.bid_number)}</span><span class="sub trunc" style="max-width:240px">${esc(x.t.organisation)}</span></td>
      <td>${x.us.price_rank ? `<span class="rank${x.us.price_rank === 1 ? ' l1' : ''}">L${x.us.price_rank}</span>` : '<span class="badge badge-crit">Rej</span>'}<span class="sub mono">${inr(x.us.offered_price)}</span></td>
      <td>${x.them.price_rank ? `<span class="rank${x.them.price_rank === 1 ? ' l1' : ''}">L${x.them.price_rank}</span>` : '<span class="badge badge-crit">Rej</span>'}<span class="sub mono">${inr(x.them.offered_price)}</span></td>
      <td>${x.us.outcome === 1 ? '<span class="badge badge-accent">You</span>' : x.them.outcome === 1 ? '<span class="badge badge-warn">Them</span>' : x.us.outcome === 0 ? '<span class="badge">Pending</span>' : '<span class="badge">Someone else</span>'}</td></tr>`).join('');
  return `<section class="card rise" style="--i:1">
      <div class="h2h-head"><div class="side"><span class="av">${initials(COMPANY.display_name)}</span><div style="min-width:0"><div class="sn">${esc(short(COMPANY.display_name))}</div><div class="tiny muted">This company</div></div></div>
        <span class="vs">VS</span>
        <div class="side r"><span class="av them">${initials(r.c.display_name)}</span><div style="min-width:0"><div class="sn">${esc(short(r.c.display_name))}</div><div class="tiny muted">Last met ${day(r.last)}</div></div></div></div>
      <div class="tug"><div class="bar">${ourW ? `<i style="flex:${ourW};background:var(--accent)"></i>` : ''}${other ? `<i style="flex:${other};background:var(--surface-3)"></i>` : ''}${pend ? `<i style="flex:${pend};background:var(--warn-soft)"></i>` : ''}${theirW ? `<i style="flex:${theirW};background:var(--warn)"></i>` : ''}</div>
        <div class="lbls"><span><b>${ourW}</b> you won</span><span>${n} bids together · ${other} to someone else${pend ? ' · ' + pend + ' pending' : ''}</span><span>they won <b>${theirW}</b></span></div></div>
    </section>
    <div class="g-12">
      <section class="card pad rise" style="--i:2"><div class="phead"><h3>Side by side</h3><span class="sub">on the ${n} shared bids</span></div>${cmpRows}
        <p class="tiny muted" style="margin-top:12px">${gap == null ? 'No bid where both were priced.' : `When both were priced, your offer averaged <b class="mono">${(gap * 100).toFixed(1)}%</b> ${gap < 0 ? 'below' : 'above'} theirs.`}</p></section>
      <section class="card pad rise" style="--i:3"><div class="phead"><h3>Meetings per month</h3><div class="row gap12 wrapf"><span class="lg"><span class="sw" style="background:var(--accent)"></span>You won</span><span class="lg"><span class="sw" style="background:var(--warn)"></span>They won</span><span class="lg"><span class="sw" style="background:var(--border-strong)"></span>Other</span></div></div>
        ${stackChart(m)}<div class="eyebrow" style="margin:14px 0 8px">Where you meet</div><div class="row gap6 wrapf">${catChips}</div></section>
    </div>
    <section class="card rise" style="--i:4"><div class="toolbar"><h3>Bids you both made</h3><span class="sub mono muted small" style="margin-left:auto">latest ${Math.min(40, n)} of ${n}</span></div>
      <div class="scroll-x"><table class="tbl"><thead><tr><th>Bid end</th><th>Bid and authority</th><th>You</th><th>${esc(short(r.c.display_name).split(' ').slice(0, 2).join(' '))}</th><th>Won by</th></tr></thead><tbody>${table}</tbody></table></div></section>`;
}
function stackChart(data) {
  const W = 520, Ht = 170, Lp = 24, Rp = 4, Tp = 6, Bp = 22;
  const max = Math.max(1, ...data.map(([, o]) => o.us + o.them + o.oth)), step = niceStep(max, 4), top = Math.ceil(max / step) * step;
  const y = v => Tp + (Ht - Tp - Bp) * (1 - v / top), bw = (W - Lp - Rp) / data.length;
  let g = '';
  for (let v = 0; v <= top; v += step) g += `<line class="grid" x1="${Lp}" x2="${W - Rp}" y1="${y(v)}" y2="${y(v)}"/><text class="lbl" x="${Lp - 5}" y="${y(v) + 3}" text-anchor="end">${v}</text>`;
  const every = Math.ceil(data.length / 7);
  data.forEach(([k, o], i) => {
    const w = Math.min(bw * .6, 16), x = Lp + i * bw + (bw - w) / 2; let base = 0;
    for (const [key, col] of [['us', 'var(--accent)'], ['them', 'var(--warn)'], ['oth', 'var(--border-strong)']]) {
      if (!o[key]) continue;
      g += `<rect x="${x.toFixed(1)}" y="${y(base + o[key]).toFixed(1)}" width="${w.toFixed(1)}" height="${(y(base) - y(base + o[key])).toFixed(1)}" rx="2" style="fill:${col}"/>`; base += o[key];
    }
    if (i % every === 0) { const [yy, mm] = k.split('-'); g += `<text class="lbl" x="${(x + w / 2).toFixed(1)}" y="${Ht - 5}" text-anchor="middle">${MON[+mm - 1]} ${yy.slice(2)}</text>`; }
  });
  return `<div class="chart"><svg viewBox="0 0 ${W} ${Ht}" role="img" aria-label="Meetings per month">${g}</svg></div>`;
}

/* ---------- events ---------- */
function setHash(h) { try { history.replaceState(null, '', '#' + h); } catch (e) {} }
function go(section) { state.section = section; state.anim = true; if (section === 'competitors') state.comp.id = null; setHash(section); render(); window.scrollTo(0, 0); }
async function openRival(id) {
  state.section = 'competitors'; state.comp.id = id; state.anim = true; setHash('vs-' + id);
  if (!LOADED.has(id)) {
    document.getElementById('view').innerHTML = '<div class="empty"><strong>Loading the head to head…</strong></div>';
    try { await loadRival(id); } catch (e) { state.comp.id = null; render(); return; }
  }
  render(); window.scrollTo(0, 0);
}
document.addEventListener('click', e => {
  const t = e.target.closest('button');
  if (!t) return;
  const d = t.dataset;
  if (d.go) return go(d.go);
  if (d.period) { state.period = d.period; state.anim = true; return render(); }
  if (d.ofilter) { state.org.filter = d.ofilter; return render(); }
  if (d.metric && !t.disabled) { state.org.metric = d.metric; return render(); }
  if (d.state) { state.org.state = state.org.state === d.state ? null : d.state; return render(); }
  if (d.bf) { state.bids.f = d.bf; state.bids.page = 0; return render(); }
  if (d.page) { state.bids.page += +d.page; return render(); }
  if (d.csort) { state.comp.sort = d.csort; return render(); }
  if (d.back) return go('competitors');
});
document.addEventListener('click', e => { const r = e.target.closest('[data-vs]'); if (r) openRival(+r.dataset.vs); });
document.addEventListener('keydown', e => { const r = e.target.closest && e.target.closest('tr[data-vs]'); if (r && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openRival(+r.dataset.vs); } });
document.addEventListener('click', e => { const p = e.target.closest('#mapbox path'); if (p && document.querySelector(`.srow[data-state="${CSS.escape(p.dataset.name)}"]`)) { state.org.state = state.org.state === p.dataset.name ? null : p.dataset.name; render(); } });
let typing;
document.addEventListener('input', e => {
  const id = e.target.id, v = e.target.value;
  if (!['bq', 'aq', 'cq'].includes(id)) return;
  clearTimeout(typing);
  typing = setTimeout(() => {
    if (id === 'bq') { state.bids.q = v; state.bids.page = 0; } else if (id === 'aq') state.auth.q = v; else state.comp.q = v;
    render();
    const el = document.getElementById(id); if (el) { el.focus(); el.setSelectionRange(v.length, v.length); }
  }, 160);
});
/* ---------- company search (the start page) ---------- */
const home = { q: '', rows: null, error: '' };
function homeView() {
  const rows = home.rows, typed = home.q.trim().length >= 2;
  const body = (rows || []).map(c => `<tr class="clickable" data-co="${c.company_id}" tabindex="0">
      <td><span class="row gap10"><span class="av sm">${initials(c.display_name)}</span><a class="name" href="?c=${c.company_id}">${esc(title(c.display_name))}</a></span></td>
      <td class="r">${num(c.total_bids)}</td><td class="r">${num(c.awarded_bids)}</td><td class="r hide-sm">${pct(c.win_rate)}</td>
      <td class="r"><b>${inr(c.awarded_value)}</b></td><td class="go">${icon('arrow', 15)}</td></tr>`).join('');
  const list = home.error ? `<div class="empty"><strong>${esc(home.error)}</strong><span>Try again in a moment.</span></div>`
    : rows == null ? `<div class="empty"><strong>Loading…</strong></div>`
    : rows.length ? `<div class="scroll-x"><table class="tbl"><thead><tr><th>Company</th><th class="r">Bids</th><th class="r">Won</th><th class="r hide-sm">Win rate</th><th class="r">Awarded value</th><th></th></tr></thead><tbody>${body}</tbody></table></div>`
    : `<div class="empty"><strong>No company matches “${esc(home.q)}”</strong><span>Try part of the name.</span></div>`;
  return `<div class="pagehead rise" style="--i:0"><div class="eyebrow">Companies</div><h1 style="margin-top:4px">Find a company</h1></div>
    <section class="card rise" style="--i:1">
      <div class="toolbar"><div class="search" style="width:min(420px,100%)">${icon('search', 15)}<input class="input" id="hq" type="search" placeholder="Company name, at least 2 letters" value="${esc(home.q)}" aria-label="Search companies"></div>
        <span class="sub small muted" style="margin-left:auto">${typed ? 'Best matches, most bids first' : 'Most active companies'}</span></div>
      ${list}</section>`;
}
function renderHome() {
  document.getElementById('sidenav').innerHTML = `<div class="sidegrp">${NAME}</div><button class="sideitem on">${icon('search')}<span>Find a company</span></button>`;
  document.getElementById('mtabs').innerHTML = '';
  document.getElementById('crumbs').innerHTML = '<span>Companies</span>';
  document.getElementById('period').innerHTML = '';
  document.getElementById('view').innerHTML = homeView();
}
async function searchCompanies() {
  const q = home.q;
  try { const d = await getJSON('/api/companies?q=' + encodeURIComponent(q.trim())); if (q !== home.q) return; home.rows = d.companies; home.error = ''; }
  catch (e) { home.error = e.message; }
  renderHome();
  const el = document.getElementById('hq'); if (el && q) { el.focus(); el.setSelectionRange(q.length, q.length); }
}
let homeTyping;
document.addEventListener('input', e => {
  if (e.target.id !== 'hq') return;
  home.q = e.target.value; clearTimeout(homeTyping); homeTyping = setTimeout(searchCompanies, 250);
});
document.addEventListener('click', e => { const r = e.target.closest('tr[data-co]'); if (r && !e.target.closest('a')) location.href = '?c=' + r.dataset.co; });
document.addEventListener('keydown', e => { const r = e.target.closest && e.target.closest('tr[data-co]'); if (r && e.key === 'Enter') location.href = '?c=' + r.dataset.co; });

/* ---------- start ---------- */
(async () => {
  const id = new URLSearchParams(location.search).get('c');
  const view = document.getElementById('view');
  fetch('india.json').then(r => r.json()).then(paths => { INDIA = paths; if (COMPANY) render(); }).catch(() => {});
  if (!id) { renderHome(); return searchCompanies(); }
  view.innerHTML = '<div class="empty"><strong>Loading company…</strong><span>Bids, authorities and competitors.</span></div>';
  try { await loadCompany(id); }
  catch (e) { view.innerHTML = `<div class="empty"><strong>${esc(e.message)}</strong><a class="btn" href="./">Find a company</a></div>`; return; }
  document.title = title(COMPANY.display_name) + ' · ' + NAME;
  if (LIMITED) { const n = document.getElementById('note'); n.hidden = false; n.textContent = 'Latest bids only'; n.title = 'This company has more bids than the page loads; the oldest are left out.'; }
  const startAt = location.hash.slice(1);
  if (SECTIONS.some(s => s[0] === startAt)) state.section = startAt;
  const vsAt = /^vs-(\d+)$/.exec(startAt);
  if (vsAt) { state.section = 'competitors'; state.comp.id = +vsAt[1]; try { await loadRival(+vsAt[1]); } catch (e) { state.comp.id = null; } }
  state.anim = true;
  render();
})();
addEventListener('hashchange', () => { const h = location.hash.slice(1), vs = /^vs-(\d+)$/.exec(h); if (!COMPANY) return;
  if (vs) { if (+vs[1] !== state.comp.id) openRival(+vs[1]); } else if (SECTIONS.some(s => s[0] === h) && h !== state.section) go(h); });
